let raw = '';

try {
  raw = $input.first().json.output[0].content[0].text;
} catch (e) {
  raw = '';
}

if (!raw || typeof raw !== 'string') {
  return [{ json: { error: true, message: 'No text found from Message a Model node', raw_output: JSON.stringify($input.first().json) } }];
}

raw = raw.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();

const firstBrace = raw.indexOf('{');
const lastBrace = raw.lastIndexOf('}');

if (firstBrace === -1 || lastBrace === -1) {
  return [{ json: { error: true, message: 'Model returned non-JSON output', raw_output: raw } }];
}

raw = raw.slice(firstBrace, lastBrace + 1);

let data;
try {
  data = JSON.parse(raw);
} catch (e) {
  return [{ json: { error: true, message: 'JSON parse failed', parse_error: e.message, raw_output: raw } }];
}

const source = $('Get row(s) in sheet').first().json;

const cleanSlug = (data.slug || source.slug || '')
  .toString()
  .trim()
  .toLowerCase()
  .replace(/^\/+|\/+$/g, '')
  .replace(/\s+/g, '-')
  .replace(/[^a-z0-9\/-]+/g, '-')
  .replace(/-+/g, '-');

const pageTitle = data.title || source.page_title || data.seo_title || '';
const focus = data.focus_keyphrase || source.focus_keyword || data.focuskw || data.keyphrase || '';
const city = source.city || '';
const state = source.state || '';
const pageType = source.page_type || '';
const alt = data.image_alt || data.alt_tag || source.alt_text || `${focus} display solution${city ? ' in ' + city : ''}`;
const mediaTitle = data.image_title || `${pageTitle || focus || pageType} Image`.trim();
const mediaDescription = data.image_description || `${alt}. Commercial LED display visual for ${pageTitle || focus || pageType}${city || state ? ' serving ' + [city, state].filter(Boolean).join(', ') : ''}.`;

function stripTags(html) {
  return String(html || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/\s+/g, ' ')
    .trim();
}

function countWords(value) {
  const text = stripTags(value);
  return text ? text.split(/\s+/).filter(Boolean).length : 0;
}

function extractInternalLinks(html) {
  const links = [];
  const regex = /href=["']([^"']+)["']/gi;
  let match;
  while ((match = regex.exec(String(html || ''))) !== null) {
    const href = String(match[1] || '').trim();
    if (!href || href.startsWith('#') || href.startsWith('mailto:') || href.startsWith('tel:')) {
      continue;
    }
    if (href.startsWith('/')) {
      links.push(href);
      continue;
    }
    try {
      const url = new URL(href);
      if (url.hostname.toLowerCase() === 'leddisplaywarehouse.com') {
        links.push(href);
      }
    } catch {
      // ignore malformed links
    }
  }
  return links;
}

function parseLinkCandidates(value) {
  if (Array.isArray(value)) {
    return value.map((entry) => String(entry || '').trim()).filter(Boolean);
  }

  if (typeof value === 'string') {
    return value
      .split(/[\n,|]/)
      .map((entry) => entry.trim())
      .filter(Boolean);
  }

  return [];
}

function toAnchor(url, label) {
  return `<a href="${url}">${label}</a>`;
}

function buildExpansionSection(topic, cityName, stateName) {
  const location = [cityName, stateName].filter(Boolean).join(', ');
  const headline = topic || 'commercial LED video walls';
  return `
<section>
  <h2>Planning a Reliable ${headline} Project${location ? ' in ' + location : ''}</h2>
  <p>Successful LED projects begin with a site plan that connects viewing distance, pixel pitch, content type, and daily operating conditions. Teams should define who will use the display, what messages will run most often, and how frequently creative assets will change. This prevents over-specification and keeps hardware, controls, and installation effort aligned with business outcomes.</p>
  <p>Before fabrication, installers should verify access paths, power availability, rigging constraints, and service clearance. These checkpoints reduce deployment risk and help maintain predictable commissioning schedules. A disciplined pre-install checklist also improves long-term maintenance by ensuring replacement parts, cable paths, and controller access remain practical after handoff.</p>
  <p>Content strategy is equally important. Operators should prepare scene templates for promotions, wayfinding, and proof-of-performance loops so the display is useful from day one. Standardized content dimensions, contrast-safe typography, and brightness profiles improve readability across indoor and outdoor conditions while protecting panel life and reducing rework for design teams.</p>
  <p>Finally, establish an operations rhythm with preventive inspections, calibration windows, and measurable service targets. Monitoring cabinet health, signal integrity, and thermal behavior over time helps teams detect issues early and keep uptime high. This operating model turns the display from a one-time install into a dependable communications platform that consistently supports revenue, branding, and customer experience goals.</p>
</section>`;
}

function ensureMinimumBodyContent(html, context) {
  let output = String(html || '').trim();

  if (!output) {
    output = `<p>${context.pageTitle || context.focus || 'Commercial LED display'} overview.</p>`;
  }

  let words = countWords(output);
  let guard = 0;
  while (words < 1225 && guard < 4) {
    output += buildExpansionSection(context.focus || context.pageTitle || 'LED display', context.city, context.state);
    words = countWords(output);
    guard += 1;
  }

  return output;
}

function ensureMinimumInternalLinks(html, candidates) {
  const existing = extractInternalLinks(html);
  if (existing.length >= 3) {
    return html;
  }

  const fallback = [
    'https://leddisplaywarehouse.com/direct-view-led-video-walls/',
    'https://leddisplaywarehouse.com/outdoor-led-displays/',
    'https://leddisplaywarehouse.com/contact-us/',
    'https://leddisplaywarehouse.com/custom-led-displays/',
  ];

  const merged = [...candidates, ...fallback]
    .map((url) => String(url || '').trim())
    .filter((url) => /^https:\/\/leddisplaywarehouse\.com\//i.test(url));

  const unique = [];
  for (const url of merged) {
    if (!unique.includes(url)) {
      unique.push(url);
    }
  }

  const needed = Math.max(3 - existing.length, 0);
  const selected = unique.slice(0, needed > 0 ? needed : 3);
  if (selected.length === 0) {
    return html;
  }

  const anchors = selected
    .map((url, index) => `<li>${toAnchor(url, 'Related resource ' + (index + 1))}</li>`)
    .join('');

  return html + `\n<section><h2>Related Resources</h2><ul>${anchors}</ul></section>`;
}

const linkCandidates = parseLinkCandidates(source.internal_links);
const rawArticleHtml = data.content || data.article_html || source.body_html || data.html || '';
let remediatedArticleHtml = ensureMinimumBodyContent(rawArticleHtml, {
  pageTitle,
  focus,
  city,
  state,
});
remediatedArticleHtml = ensureMinimumInternalLinks(remediatedArticleHtml, linkCandidates);

return [{
  json: {
    source_mode: source.source_mode || 'sheet',
    job_id: source.job_id || '',
    callback_url: source.callback_url || '',
    publishing_mode: source.publishing_mode === 'publish' ? 'publish' : 'draft',
    additional_instructions: source.additional_instructions || '',
    page_type: pageType,
    state,
    city,
    post_title: pageTitle,
    page_title: pageTitle,
    seo_title: data.seo_title || pageTitle || '',
    h1: data.h1 || source.h1 || pageTitle || '',
    slug: cleanSlug,
    meta_description: data.meta_description || data.metadesc || data.description || '',
    focus_keyphrase: focus,
    alt_tag: alt,
    media_title: mediaTitle,
    media_description: mediaDescription,
    image_prompt: data.image_prompt || source.image_prompt || data.prompt || '',
    article_html: remediatedArticleHtml,
    excerpt: data.excerpt || data.meta_description || '',
    internal_links: source.internal_links || '',
    source_row_number: source.row_number || '',
    source_status: source.status || ''
  }
}];

const item = $input.first().json;

function slugify(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/&/g, 'and')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function normalizeText(value) {
  return String(value || '')
    .trim()
    .toLowerCase();
}

const isGlw = String(item.source_mode || '').toLowerCase() === 'glw';

/*
 * Canonical WordPress product mappings.
 */
const productMap = {
  'led video walls': 'direct-view-led-video-walls',
  'direct view led video walls': 'direct-view-led-video-walls',
  'direct-view led video walls': 'direct-view-led-video-walls',

  'led wall rental': 'direct-view-led-video-walls',
  'led wall rentals': 'direct-view-led-video-walls',
  'led video wall rental': 'direct-view-led-video-walls',
  'led video wall rentals': 'direct-view-led-video-walls',

  'outdoor led displays': 'outdoor-led-displays',
  'church led walls': 'church-led-walls',
  'trade show led displays': 'trade-show-led-displays',
  'transparent led displays': 'transparent-led-displays',
  'creative led displays': 'creative-led-displays',
  'interactive led floors': 'interactive-led-floors',
  'led posters': 'led-posters',
  'custom led displays': 'custom-led-displays',

  'cob all-in-one led displays': 'cob-all-in-one-led-displays',
  'cob all in one led displays': 'cob-all-in-one-led-displays',

  'smd all-in-one led displays': 'smd-all-in-one-led-displays',
  'smd all in one led displays': 'smd-all-in-one-led-displays',

  'exhibition led displays': 'exhibition-led-displays',

  'flexible rollable led displays': 'flexible-rollable-led',
  'flexible and rollable led displays': 'flexible-rollable-led',
  'flexible & rollable led': 'flexible-rollable-led',
  'flexible and rollable led': 'flexible-rollable-led',

  'led fan displays': 'led-fans',
  'led fans': 'led-fans'
};

const slugAliasMap = {
  'led-video-walls': 'direct-view-led-video-walls',
  'direct-view-led-video-walls': 'direct-view-led-video-walls',

  'led-wall-rental': 'direct-view-led-video-walls',
  'led-wall-rentals': 'direct-view-led-video-walls',
  'led-video-wall-rental': 'direct-view-led-video-walls',
  'led-video-wall-rentals': 'direct-view-led-video-walls',

  'outdoor-led-displays': 'outdoor-led-displays',
  'church-led-walls': 'church-led-walls',
  'trade-show-led-displays': 'trade-show-led-displays',
  'transparent-led-displays': 'transparent-led-displays',
  'creative-led-displays': 'creative-led-displays',
  'interactive-led-floors': 'interactive-led-floors',
  'led-posters': 'led-posters',
  'custom-led-displays': 'custom-led-displays',
  'cob-all-in-one-led-displays': 'cob-all-in-one-led-displays',
  'smd-all-in-one-led-displays': 'smd-all-in-one-led-displays',
  'exhibition-led-displays': 'exhibition-led-displays',
  'flexible-rollable-led': 'flexible-rollable-led',
  'led-fans': 'led-fans'
};

/*
 * These are page types, NOT product categories.
 */
const genericPageTypes = new Set([
  'city_service',
  'city-service',
  'city',
  'state',
  'state_service',
  'state-service',
  'service',
  'location',
  'location_service',
  'location-service',
  'page_generation',
  'page-generation'
]);

/*
 * Always trust structured geographic fields.
 */
const stateSlug = slugify(item.state);
const citySlug = slugify(item.city);

/*
 * Try to resolve the canonical product.
 */
const productCandidates = [
  item.product,
  item.product_topic,
  item.productTopic,
  item.service,
  item.service_name,
  item.focus_keyword,
  item.focus_keyphrase
];

const pageTypeValue = normalizeText(item.page_type);

if (
  pageTypeValue &&
  !genericPageTypes.has(pageTypeValue)
) {
  productCandidates.push(item.page_type);
}

let productSlug = '';

for (const candidate of productCandidates) {
  const normalized = normalizeText(candidate);

  if (!normalized) {
    continue;
  }

  if (productMap[normalized]) {
    productSlug = productMap[normalized];
    break;
  }

  const candidateSlug = slugify(candidate);

  if (slugAliasMap[candidateSlug]) {
    productSlug = slugAliasMap[candidateSlug];
    break;
  }
}

/*
 * Existing product_slug fallback.
 */
if (!productSlug) {
  const existingProductSlug = slugify(item.product_slug);

  if (existingProductSlug && slugAliasMap[existingProductSlug]) {
    productSlug = slugAliasMap[existingProductSlug];
  }
}

/*
 * Raw slug fallback.
 *
 * IMPORTANT:
 * We may recover a recognized PRODUCT slug here.
 * We never recover state/city from item.slug.
 */
if (!productSlug) {
  const rawSlug = String(item.slug || '')
    .trim()
    .toLowerCase()
    .replace(/^\/+|\/+$/g, '');

  const parts = rawSlug
    .split('/')
    .map((part) => slugify(part))
    .filter(Boolean);

  for (const part of parts) {
    if (slugAliasMap[part]) {
      productSlug = slugAliasMap[part];
      break;
    }
  }
}

/*
 * LEGACY SHEET MODE
 *
 * Preserve prior behavior for old sheet/schedule rows.
 * Do not allow a legacy test row to break the entire workflow.
 */
if (!isGlw && !productSlug) {
  productSlug = slugify(item.page_type || item.product || '');
}

/*
 * GLW SAFETY GATES
 *
 * GLW is the production page-generation path.
 * It must never invent malformed hierarchy.
 */
if (isGlw && !productSlug) {
  throw new Error(
    [
      'GLW: Unable to resolve canonical product parent.',
      `page_type="${item.page_type || ''}"`,
      `category="${item.category || ''}"`,
      `focus_keyword="${item.focus_keyword || ''}"`,
      `product="${item.product || ''}"`,
      `product_topic="${item.product_topic || item.productTopic || ''}"`
    ].join(' ')
  );
}

if (isGlw && !stateSlug) {
  throw new Error(
    `GLW: Unable to resolve state slug from state="${item.state || ''}".`
  );
}

if (isGlw && !citySlug) {
  throw new Error(
    `GLW: Unable to resolve city slug from city="${item.city || ''}".`
  );
}

/*
 * For legacy sheet rows, preserve safe empty handling.
 */
const finalProductSlug = productSlug || '';
const finalStateSlug = stateSlug || '';
const finalCitySlug = citySlug || '';

const desiredHierarchicalSlug = [
  finalProductSlug,
  finalStateSlug,
  finalCitySlug
]
  .filter(Boolean)
  .join('/');

return [
  {
    json: {
      ...item,

      product_slug: finalProductSlug,
      state_slug: finalStateSlug,
      city_slug: finalCitySlug,

      desired_hierarchical_slug: desiredHierarchicalSlug
    }
  }
];

const response = $input.first().json;
const source = $('Prepare Hierarchy Fields').first().json;

let product = {};

if (Array.isArray(response)) {
  product = response[0] || {};
} else if (Array.isArray(response.data)) {
  product = response.data[0] || {};
} else if (response && response.id) {
  product = response;
}

return [{
  json: {
    ...source,
    product_parent_id: Number(product.id || 0),
    product_parent_found: !!product.id,
    product_parent_link: product.link || '',
    product_parent_title: product.title?.rendered || ''
  }
}];

const response = $input.first().json;
const source = $('Prepare Product Parent').first().json;

let list = [];

if (Array.isArray(response)) {
  list = response;
} else if (Array.isArray(response.body)) {
  list = response.body;
} else if (Array.isArray(response.data)) {
  list = response.data;
} else if (response && response.id) {
  list = [response];
}

const statePage = list.find(p => p && p.id) || {};

return [{
  json: {
    ...source,
    state_parent_id: Number(statePage.id || 0),
    state_parent_found: !!statePage.id,
    needs_state_parent: !statePage.id,
    state_parent_link: statePage.link || '',
    state_parent_slug: statePage.slug || ''
  }
}];

const created = $input.first().json;
const source = $('Prepare Product Parent').first().json;

const stateParentId = Number(created.id || 0);

if (!stateParentId) {
  throw new Error('Missing state parent ID after create attempt.');
}

return [{ json: { ...source, state_parent_id: stateParentId, state_parent_found: true, created_state_parent: true } }];

const item = $input.first().json;

let valid = true;
let errorCode = '';
let errorMessage = '';

if (!item.state_parent_id || Number(item.state_parent_id) <= 0) {
  valid = false;
  errorCode = 'MISSING_STATE_PARENT_ID';
  errorMessage = `Missing state_parent_id. Refusing to publish root-level page. product=${item.product_slug || ''}, state=${item.state_slug || ''}, city=${item.city_slug || ''}`;
} else if (!item.city_slug) {
  valid = false;
  errorCode = 'MISSING_CITY_SLUG';
  errorMessage = 'Missing city_slug. Refusing to publish page.';
}

return [{
  json: {
    ...item,
    valid,
    validation_error_code: errorCode,
    validation_error_message: errorMessage,
    validation_error_node: 'Validate Parent Before Publish'
  }
}];

// Get all rows
const rows = $input.all();

// Find the first Ready row
const ready = rows.find(r => {
  const status = String(r.json.Status || r.json.status || "")
    .trim()
    .toLowerCase();

  return status === "ready";
});

// Nothing ready? Stop workflow.
if (!ready) {
  return [];
}

// Return ONLY one record
return [ready];

const input = $input.first().json;
const body =
  input.body && typeof input.body === 'object'
    ? input.body
    : input;

const isGlw = Boolean(
  body.jobId ||
  body.type === 'page_generation' ||
  body.page ||
  body.workflowContext ||
  body.publishingSettings
);

function slugify(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/&/g, 'and')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function normalizePublishingMode(...values) {
  for (const value of values) {
    if (value === undefined || value === null || value === '') continue;

    const normalized = String(value).trim().toLowerCase();

    if (normalized === 'publish' || normalized === 'published') {
      return 'publish';
    }

    if (normalized === 'draft') {
      return isGlw ? 'publish' : 'draft';
    }
  }

  return isGlw ? 'publish' : 'draft';
}

if (!isGlw) {
  return [
    {
      json: {
        ...input,
        source_mode: 'sheet',
        publishing_mode: normalizePublishingMode(
          input.publishing_mode,
          input.publishingMode,
          input.status
        ),
        job_id: '',
        callback_url: ''
      }
    }
  ];
}

const page = body.page || {};
const site = body.site || {};
const publishingSettings =
  body.publishingSettings &&
  typeof body.publishingSettings === 'object'
    ? body.publishingSettings
    : {};

const workflowContext =
  body.workflowContext &&
  typeof body.workflowContext === 'object'
    ? body.workflowContext
    : {};

const seoSettings =
  body.seoSettings &&
  typeof body.seoSettings === 'object'
    ? body.seoSettings
    : {};

const product = String(
  page.product ||
  page.productTopic ||
  workflowContext.productTopic ||
  page.category ||
  seoSettings.category ||
  ''
).trim();

const category = String(
  page.category ||
  seoSettings.category ||
  page.product ||
  page.productTopic ||
  workflowContext.productTopic ||
  ''
).trim();

const state = String(
  page.state ||
  workflowContext.state ||
  ''
).trim();

const city = String(
  page.city ||
  workflowContext.city ||
  ''
).trim();

const focusKeyword = String(
  page.primaryKeyword ||
  seoSettings.primaryKeyword ||
  ''
).trim();

const jobId = String(
  body.jobId ||
  body.job_id ||
  ''
).trim();

const callbackUrl = String(
  body.callbackUrl ||
  body.callback_url ||
  ''
).trim();

if (!jobId) {
  throw new Error('GLW request is missing jobId.');
}

if (!product) {
  throw new Error(
    'GLW request is missing page.product, page.productTopic, workflowContext.productTopic, or page.category.'
  );
}

if (!focusKeyword) {
  throw new Error(
    'GLW request is missing page.primaryKeyword or seoSettings.primaryKeyword.'
  );
}

if (site.id && site.id !== 'led-display-warehouse') {
  throw new Error(`Unsupported GLW site: ${site.id}`);
}

const productSlug = slugify(
  page.productSlug ||
  page.targetSlug ||
  seoSettings.targetSlug ||
  product
);

const stateSlug = slugify(
  page.stateSlug ||
  state
);

const citySlug = slugify(
  page.citySlug ||
  seoSettings.citySlug ||
  seoSettings.city_slug ||
  workflowContext.citySlug ||
  city
);

const hierarchicalSlug = String(
  page.hierarchicalSlug ||
  page.hierarchical_slug ||
  seoSettings.hierarchicalSlug ||
  workflowContext.hierarchicalSlug ||
  ''
).trim();

const slugParts = hierarchicalSlug
  ? hierarchicalSlug
      .split('/')
      .map((part) => slugify(part))
      .filter(Boolean)
  : [productSlug, stateSlug, citySlug].filter(Boolean);

const requestedTitle = String(
  page.pageTitle ||
  page.page_title ||
  page.title ||
  ''
).trim();

const requestedH1 = String(
  page.h1 ||
  ''
).trim();

const wordCount = Number(
  publishingSettings.wordCount ||
  page.wordCount ||
  page.word_count ||
  1500
);

const additionalInstructions = String(
  page.additionalInstructions ||
  page.additional_instructions ||
  workflowContext.additionalInstructions ||
  workflowContext.additional_instructions ||
  ''
).trim();

const publishingMode = normalizePublishingMode(
  body.publishing_mode,
  body.publishingMode,
  publishingSettings.status,
  page.publishingMode,
  page.publishing_mode,
  page.status
);

return [
  {
    json: {
      source_mode: 'glw',
      job_id: jobId,
      callback_url: callbackUrl,

      publishing_mode: publishingMode,

      site_id: site.id || 'led-display-warehouse',
      site_name: site.name || 'LED Display Warehouse',

      page_type: String(
        page.page_type ||
        page.pageType ||
        workflowContext.pageType ||
        product
      ).trim(),

      category,
      state,
      city,
      focus_keyword: focusKeyword,

      slug: slugParts.join('/'),

      page_title: requestedTitle,
      h1: requestedH1,

      internal_links: '',

      word_count:
        Number.isFinite(wordCount) && wordCount > 0
          ? wordCount
          : 1500,

      additional_instructions: additionalInstructions,

      status: 'Ready',
      row_number: ''
    }
  }
];

const crypto = require('node:crypto');
const source = $('Get row(s) in sheet').first().json;
const request = $('GLW Page Webhook').first().json.body || $('GLW Page Webhook').first().json;
let qa = {};
try { qa = $('Build Pre-Publish QA Result').first().json; } catch {}
const failed = $json.validation_error_message;
